  1243      fn field_ty(
  1244          infcx: &InferCtxt<'db>,
  1245          self_ty: Ty<'db>,
  1246          variant: Option<VariantId>,
  1247          f: FieldIndex,
  1248      ) -> Ty<'db> {
  1249          if let Some(variant_id) = variant {
  1250              match self_ty.kind() {
  1251                  TyKind::Adt(adt_def, args) if adt_def.is_enum() => {
  1252                      infcx.interner.db().field_types(variant_id)[f.to_local_field_id()]
  1253                          .ty()
  1254                          .instantiate(infcx.interner, args)
  1255                          .skip_norm_wip()
  1256                  }
  1257                  // FIXME TyKind::Coroutine...
  1258                  _ => panic!("can't downcast non-adt non-coroutine type: {self_ty:?}"),
  1259              }
  1260          } else {
  1261              match self_ty.kind() {
  1262                  TyKind::Adt(adt_def, args) if !adt_def.is_enum() => {
  1263                      let variant_id = VariantId::from_non_enum(adt_def.def_id()).unwrap();
  1264                      infcx.interner.db().field_types(variant_id)[f.to_local_field_id()]
  1265                          .ty()
  1266                          .instantiate(infcx.interner, args)
  1267                          .skip_norm_wip()
  1268                  }
  1269                  TyKind::Closure(_, args) => {
  1270                      args.as_closure().tupled_upvars_ty().tuple_fields()[f.0 as usize]
  1271                  }
  1272                  // FIXME TyKind::Coroutine / TyKind::CoroutineClosure...
  1273                  TyKind::Tuple(tys) => tys
  1274                      .get(f.0 as usize)
  1275                      .cloned()
  1276                      .unwrap_or_else(|| panic!("field {f:?} out of range: {self_ty:?}")),
  1277                  _ => panic!("can't project out of {self_ty:?}"),
  1278              }
  1279          }
  1280      }
